**Step 2: Ensure `TranscriptionCoordinator` is correctly set up**

```swift
// Fieldnotes/Core/Transcription/TranscriptionCoordinator.swift

final class TranscriptionCoordinator {
    static let shared = TranscriptionCoordinator()

    func transcribe(entryID: UUID) -> Task<Void, Never> {
        return Task {
            // Check availability
            if SpeechAvailabilityState.ready == Self.availability(for: Locale.current) {
                // Perform transcription
                try await self.performTranscription(forEntryID: entryID)
            } else {
                // Handle unavailable case (e.g., update the entry status to unavailable)
                let context = ModelContainerFactory.make(cloudKitEnabled: false).backgroundContext
                let entry = try! context.query(for: Entry.self, where: #Predicate<Entry> { $0.id == entryID }).first!
                entry.transcriptionStatus = .unavailable
            }
        }
    }

    private func performTranscription(forEntryID entryID: UUID) async throws {
        // Get the model container and entry
        let context = ModelContainerFactory.make(cloudKitEnabled: false).backgroundContext
        let entry = try! context.query(for: Entry.self, where: #Predicate<Entry> { $0.id == entryID }).first!

        // Set transcription status to transcribing
        entry.transcriptionStatus = .transcribing

        // Get the audio file URL
        guard let audioFileURL = AppGroupConfig.containerURL.appendingPathComponent(entry.audioRelativePath) else {
            throw TranscriptionError.fileNotFound
        }

        // Initialize Speech recognizer and start transcription
        let recognizer = SFSpeechRecognizer()
        let request = SFSpeechURLRecognitionRequest(url: audioFileURL)
        try await recognizer.recognitionTask(with: request) { result, error in
            if let result = result {
                // Update transcript text
                entry.cachedTranscriptText = result.bestTranscription.formattedString
                entry.transcriptionStatus = .completed
            } else if let error = error {
                // Handle error
                print("Transcription error: \(error.localizedDescription)")
                entry.transcriptionStatus = .unavailable
            }
        }

        try await context.save()
    }
}
```

### What works now:
- `RecordingController` now triggers transcription after a recording is finalized.
- `TranscriptionCoordinator` correctly handles transcription and updates the entry's status.

### What remains:
